Proceso ContarFinesDeSemana
    Definir cantidad Como Entero;
    Definir i Como Entero;
    Definir dia Como Entero;
    Definir cuenta Como Entero;
    Leer cantidad;
    cuenta <- 0;
    Para i <- 1 Hasta cantidad Hacer
        Leer dia;
        Si dia = 6 O dia = 7 Entonces
            cuenta <- cuenta + 1;
        FinSi
    FinPara
    Escribir cuenta;
FinProceso
